export type SessionMessageToolStatePending = {
  status: "pending"
  input: string
}

export type ToolTextContent = {
  type: "text"
  text: string
}

export type ToolFileContent = {
  type: "file"
  uri: string
  mime: string
  name?: string
}

export type LlmToolContent = ToolTextContent | ToolFileContent

export type SessionMessageToolStateRunning = {
  status: "running"
  input: {
    [key: string]: unknown
  }
  structured: {
    [key: string]: unknown
  }
  content: Array<LlmToolContent>
}

export type SessionMessageToolStateCompleted = {
  status: "completed"
  input: {
    [key: string]: unknown
  }
  attachments?: Array<PromptFileAttachment>
  content: Array<LlmToolContent>
  outputPaths?: Array<string>
  structured: {
    [key: string]: unknown
  }
  result?: unknown
}

export type SessionErrorUnknown = {
  type: "unknown"
  message: string
  _tag?: string
  retryable?: boolean
  status?: number
}

export type SessionMessageToolStateError = {
  status: "error"
  input: {
    [key: string]: unknown
  }
  content: Array<LlmToolContent>
  structured: {
    [key: string]: unknown
  }
  error: SessionErrorUnknown
  result?: unknown
}

export type SessionMessageAssistantTool = {
  type: "tool"
  id: string
  name: string
  title?: string
  provider?: {
    executed: boolean
    metadata?: LlmProviderMetadata
    resultMetadata?: LlmProviderMetadata
  }
  state:
    | SessionMessageToolStatePending
    | SessionMessageToolStateRunning
    | SessionMessageToolStateCompleted
    | SessionMessageToolStateError
  time: {
    created: number
    ran?: number
    completed?: number
    pruned?: number
  }
}

export type SessionMessagePromptAnchor = {
  sessionID: string
  contextEpoch: number
  providerID: string
  modelID: string
  variant?: string
  serverKey: string
  routeID: string
  protocolID: string
  servedBy?: string
  controllerKey: string
  shapeKey: string
  heuristicTokens: number
  reportedTokens: number
}

export type SessionMessageContext = {
  window: number
  estimatedTokens: number
  droppedMessages: number
  elidedOutputs: number
  findings: Array<
    | {
        kind: "duplicate-tool-output"
        tool: string
        target?: string
        occurrences: number
        repeatedTokens: number
        elided: boolean
      }
    | {
        kind: "dominant-tool-output"
        tool: string
        target?: string
        tokens: number
        percent: number
      }
    | {
        kind: "category-budget"
        category: "system" | "messages" | "retrieval" | "memory" | "tool_output"
        limitTokens: number
        beforeTokens: number
        afterTokens: number
        affectedMessages: number
        protected: boolean
      }
  >
  promptAnchor?: SessionMessagePromptAnchor
}

export type SessionMessageAssistant = {
  id: string
  metadata?: {
    [key: string]: unknown
  }
  time: {
    created: number
    completed?: number
  }
  seq?: number
  type: "assistant"
  agent: string
  model: ModelRef
  content: Array<SessionMessageAssistantText | SessionMessageAssistantReasoning | SessionMessageAssistantTool>
  snapshot?: {
    start?: string
    end?: string
    files?: Array<string>
  }
  finish?: string
  cost?: number
  tokens?: {
    input: number
    output: number
    reasoning: number
    cache: {
      read: number
      write: number
    }
  }
  context?: SessionMessageContext
  timing?: {
    startedAt: number
    completedAt?: number
    phases: Array<{
      phase:
        | "prepare"
        | "context-load"
        | "request-build"
        | "context-fit"
        | "memory-embed"
        | "memory-search"
        | "memory-rerank"
        | "compaction"
        | "snapshot"
        | "snapshot-before"
        | "snapshot-after"
        | "scheduler-wait"
        | "provider-setup"
        | "provider-prefill"
        | "generation"
        | "capability-queue"
        | "capability-load"
        | "capability-run"
      startedAt: number
      completedAt?: number
      details?: Array<{
        phase: "repository" | "status" | "persist" | "hash"
        startedAt: number
        completedAt?: number
      }>
    }>
    providerAttempts: Array<{
      attempt: number
      dispatchedAt: number
      firstTokenAt?: number
      completedAt?: number
      outcome: "running" | "completed" | "failed" | "interrupted" | "retry"
    }>
  }
  error?: SessionErrorUnknown
}

